#!/usr/bin/env bash
# This file was generated by Cursor AI on 2026-10-21.
# Based on original Python test script.
#
# Run moxisc on every *.moxi fixture. A file whose stem ends in X is expected
# to fail; all others are expected to succeed.
#
# AddressSanitizer's llvm-symbolizer deadlocks when stdout/stderr are captured
# (as they are here so failures can print the ASan report). Disable
# symbolization in the child; the leak/error text still goes to stderr.

set -u

FILE_DIR=$(cd "$(dirname "$0")" && pwd)
EXECUTABLE="$FILE_DIR/../build/moxisc"

if [[ ! -f "$EXECUTABLE" ]]; then
    echo "error: executable not a file ($EXECUTABLE)" >&2
    exit 1
fi

# Keep any user ASAN_OPTIONS and force symbolize=0 so captured runs do not hang.
export ASAN_OPTIONS="${ASAN_OPTIONS:+${ASAN_OPTIONS}:}symbolize=0"

status=0

while IFS= read -r file; do
    base=$(basename "$file" .moxi)
    should_fail=0
    if [[ "$base" == *X ]]; then
        should_fail=1
    fi

    rc=0
    output=$("$EXECUTABLE" "$file" 2>&1) || rc=$?

    actually_fails=0
    if [[ "$rc" -ne 0 ]]; then
        actually_fails=1
    fi

    if [[ "$actually_fails" -eq 1 && "$should_fail" -eq 0 ]]; then
        echo "[FAIL] $file"
        if [[ -n "$output" ]]; then
            printf '%s\n' "$output" | sed 's/^/\t/'
        else
            echo -e "\tmoxisc returned $rc with no output"
        fi
        status=1
    elif [[ "$actually_fails" -eq 0 && "$should_fail" -eq 1 ]]; then
        echo "[FAIL] $file"
        echo -e "\tmoxisc returned 0"
        status=1
    else
        echo "[PASS] $file"
    fi
done < <(find "$FILE_DIR" -name '*.moxi' | sort)

exit "$status"
